"""
    Returns the lyrics of a song arranged by the song data.

    :param arrangement: A list of strings describing the arrangement of the
                        lyrics. We do not do checking in this function, so the
                        type must be correct.
    :type arrangement: `list(str)`

    :param song_data: Song information, conforming to the model sepecification
                      in `datamodels.py`. One of the keys has to be `lyrics`.
    :type song_data: `dict`

    :returns: `arranged_lyrics`, the lyrics arranged according to the
              specified arrangement.
    :rtype: `str`
    """
def arrange_lyrics(arrangement: Any, song_data: Any) -> object {
    arranged_lyrics = "";
    for a in arrangement {
        arranged_lyrics += song_data["lyrics"][a];
        arranged_lyrics += "\n\n";
    }
    return arranged_lyrics;
}

"""Remove any unwanted characters from the layer name.

    Args:
        name (string): the layer name.

    Returns:
        string: the filtered layer name.
    """
def get_clean_layer_name(name: Any) -> object {
    delimit_chars = ":_/";
    for char in delimit_chars {
        name = name.split(char)[0];
    }
    return name;
}

"""
    Check if a point is included into a regular rectangle that aligned with the x-y axis
    :param px: x value of the point
    :param py: y value of the point
    :param rectangle: the coordinates of the 4 corners of the rectangle
    :return: True or False depending if the point is in poly or not
    """
def point_in_rectangle(px: Any, py: Any, rectangle: Any) -> object {
    max_x_val = float("-inf");
    max_y_val = float("-inf");
    min_x_val = float("inf");
    min_y_val = float("inf");
    assert (len(rectangle) == 4);
    for p in rectangle {
        if (p[0] >= max_x_val) {
            max_x_val = p[0];
        }
        if (p[1] >= max_y_val) {
            max_y_val = p[1];
        }
        if (p[0] <= min_x_val) {
            min_x_val = p[0];
        }
        if (p[1] <= min_y_val) {
            min_y_val = p[1];
        }
    }
    return (
        (px >= min_x_val)
        and (px <= max_x_val)
        and (py >= min_y_val)
        and (py <= max_y_val)
    );
}

"""
    Compare two 1D numpy arrays lexographically
    Parameters
    ----------
    a1: ndarray
        1D numpy array
    a2: ndarray
        1D numpy array

    Returns
    -------
    comparison:
        True if a1 < a2, False otherwise
    """
def _lexographic_lt0(a1: Any, a2: Any) -> object {
    for (e1, e2) in zip(a1, a2) {
        if (e1 < e2) {
            return True;
        } elif (e1 > e2) {
            return False;
        }
    }
    return (len(a1) < len(a2));
}

