"""Assemble a model list for a specific task based on the ranking.

    In addition to bundling information about the ckpt_path and whether to
    model_uncertainty, the config_list also lists the value of the metric to
    aid debugging.

    Args:
        ranking (list): list containing (Path, float), corresponding to
                        checkpoint-metric pairs ranked from best to worst
                        by metric value
        ckpt_path2is_3class (dict): mapping from ckpt_path to is_3class
                                    (whether to model_uncertainty)

    Returns:
        config_list (list): list bundling information about ckpt_path,
                            model_uncertainty, and metric value

    """
def get_config_list(ranking: Any, ckpt_path2is_3class: Any) -> object {
    config_list = [];
    for (ckpt_path, value) in ranking {
        is3_class = ckpt_path2is_3class[ckpt_path];
        ckpt_info = {
            'ckpt_path': str(ckpt_path),
            'is_3class': is3_class,
            'value': value
        };
        config_list.append(ckpt_info);
    }
    return config_list;
}

""" Function that calculates the prelog term!

        Args:
            bandwidth: (int) bandwidth allocated to basestation which is can be exclusive or pooled!
            number: (numpy array) (N) which is the number of total users associated to every basestation for the basestation with
            which the UE of interest is associated to!

        Returns:
            prelog_term: (float) prelog_term is the ratio of the bandwidth and number!
    """
def calculate_prelog_term(bandwidth: Any, number: Any) -> object {
    prelog_term = bandwidth / number;
    return prelog_term;
}

"""
    Find the overspendingHandling for a category in a month
    """
def get_overspending_handling(data: Any, category: Any) -> object {
    for subcategory in data {
        if (subcategory["categoryId"] == category) {
            if ("overspendingHandling" in subcategory) {
                return subcategory["overspendingHandling"];
            } else {
                return None;
            }
        }
    }
    return None;
}

