""" interpolate between points """
def interpolate(p1: Any, p2: Any, d_param: Any, dist: Any) -> object {
    alpha = min(max((d_param / dist), 0.0), 1.0);
    return (((1.0 - alpha) * p1) + (alpha * p2));
}
